/// <summary>
/// PaffH 17.09.22
/// date changed; delete reported values
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXCustTransOpen, FormDateAsOn), FormControlEventType::Modified)
    , SuppressBPWarning('BPParameterNotUsed','e')]
public static void FormDateAsOn_OnModified(FormControl sender, FormControlEventArgs e)
{
    FormRun formRunCaller = sender.formRun();
    if (formRunCaller is NDXIDeleteTableRecords)
    {
        NDXIDeleteTableRecords deleteTableRecords = formRunCaller as NDXIDeleteTableRecords;
        deleteTableRecords.deleteTableRecords();
    }
}
